def compute(vars):
    high = vars["v1"]
    low = vars["v2"]
    average_price = (high + low) / 2
    return {
        "value": average_price,
        "trace": {
            "high": high,
            "low": low,
            "average_price": average_price,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "stock price per share"
            }
        }
    }
